.fx-rwd{width:min(560px,100%);border:1px solid var(--border);border-radius:var(--radius);padding:1.3em 1.4em 1.5em;background:var(--surface)}
.fx-rwd .msg{font-weight:600;margin-bottom:1.6em;min-height:1.5em}.fx-rwd .msg b{color:var(--accent)}
.fx-rwd .track{position:relative;height:.55em;border-radius:99px;background:var(--border);margin:0 1.4em 2.8em}
.fx-rwd .fill{position:absolute;left:0;top:0;bottom:0;border-radius:99px;background:linear-gradient(90deg,var(--primary),var(--accent));width:var(--w,0%);transition:width calc(.6s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-rwd .node{position:absolute;top:50%;left:var(--x);translate:-50% -50%;text-align:center}
.fx-rwd .node i{display:grid;place-items:center;width:2.1em;height:2.1em;border-radius:50%;background:var(--surface);border:2px solid var(--border);font:700 .8em var(--font-body);font-style:normal;color:color-mix(in srgb,var(--text) 55%,var(--surface));transition:all calc(.3s/var(--speed))}
.fx-rwd .node.on i{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}
.fx-rwd .node.pop i{animation:fx-rwd-p calc(.5s/var(--speed))}
.fx-rwd .node span{position:absolute;top:2.6em;left:50%;translate:-50% 0;white-space:nowrap;font:600 .74em var(--font-body);opacity:.75}
.fx-rwd .node small{display:block;font-weight:500;opacity:.8}
@keyframes fx-rwd-p{40%{transform:scale(1.35)}}
.fx-rwd .ctl{display:flex;gap:.5em;align-items:center;margin-top:.4em;flex-wrap:wrap}
.fx-rwd .ctl b{margin-right:auto}
.fx-rwd .ctl button{padding:.5em 1em;border-radius:99px;border:1px solid var(--primary);background:none;color:var(--primary);font:700 .82em var(--font-body);cursor:pointer}
.fx-rwd .ctl button.p{background:var(--primary);color:var(--on-primary)}
@media(prefers-reduced-motion:reduce){.fx-rwd .fill,.fx-rwd .node i{transition:none}.fx-rwd .node.pop i{animation:none}}

