(function(){
/* ── edit these ─────────────────────────────── */
var TIERS=[{at:150,label:'Free shipping',tag:'RM 150'},{at:300,label:'Free gift',tag:'RM 300'},{at:500,label:'10% off',tag:'RM 500'}],STEP=49,CUR='RM ';
/* ───────────────────────────────────────────── */
var r=document.querySelector('.fx-rwd'),t=r.querySelector('#fx-rwd-t'),f=t.querySelector('.fill'),m=r.querySelector('#fx-rwd-m'),s=r.querySelector('#fx-rwd-s'),max=TIERS[TIERS.length-1].at,total=0,was=[];
var nodes=TIERS.map(function(x,i){var d=document.createElement('div');d.className='node';d.style.setProperty('--x',(x.at/max*100)+'%');d.innerHTML='<i>'+(i+1)+'</i><span>'+x.label+'<small>'+x.tag+'</small></span>';t.appendChild(d);return d});
function draw(){f.style.setProperty('--w',Math.min(100,total/max*100)+'%');s.textContent='Cart '+CUR+total;
 var next=TIERS.filter(function(x){return total<x.at})[0];
 m.innerHTML=next?'Add <b>'+CUR+(next.at-total)+'</b> more to unlock <b>'+next.label.toLowerCase()+'</b>':'You unlocked every reward 🎉';
 nodes.forEach(function(n,i){var on=total>=TIERS[i].at;if(on&&!was[i]){n.classList.add('pop');setTimeout(function(){n.classList.remove('pop')},600)}n.classList.toggle('on',on);was[i]=on})}
r.querySelector('#fx-rwd-a').onclick=function(){total+=STEP;draw()};r.querySelector('#fx-rwd-r').onclick=function(){total=Math.max(0,total-STEP);draw()};
total=98;draw();was=TIERS.map(function(x){return total>=x.at})})();
